<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#faf7f4">
    <meta name="description" content="Découvrez une beauté douce et lumineuse avec Éclora Beauty.">
    <title>Éclora Beauty — La beauté, tout en douceur</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#201b1a;--muted:#827773;--paper:#faf7f4;--white:#fff;--rose:#d56d88;--rose-deep:#a34560;--blush:#f2dfe1;--line:#e9e1dc;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button{font:inherit;color:inherit}.announcement{height:34px;background:#201b1a;color:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.announcement span{color:#efb4c4;margin-left:5px}.site-header{background:#fff;position:relative;z-index:2}.header-main{height:76px;padding:0 6.2%;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:1px solid #f1ece8}.menu-toggle{display:none}.brand{font-family:var(--serif);font-size:27px;letter-spacing:.13em;font-weight:600;text-align:center}.brand span{color:var(--rose)}.header-tools{justify-self:end;display:flex;gap:22px;align-items:center}.icon-link{border:0;background:transparent;padding:6px;cursor:pointer;display:inline-flex;align-items:center;gap:7px;font-size:11px}.icon-link svg{width:19px;height:19px;stroke:currentColor;fill:none;stroke-width:1.5}.cart-count{font-size:10px;background:var(--rose);color:white;border-radius:50%;height:17px;width:17px;display:inline-grid;place-items:center}.nav{height:45px;display:flex;justify-content:center;align-items:center;gap:39px;font-size:10px;letter-spacing:.13em;text-transform:uppercase}.nav a{transition:color .2s}.nav a:hover{color:var(--rose-deep)}.hero{max-width:1512px;margin:auto;padding:0 4.4%;}.hero-panel{min-height:530px;display:grid;grid-template-columns:.9fr 1.1fr;background:#f0e4e1;overflow:hidden;position:relative}.hero-copy{padding:82px 8% 60px 12%;align-self:center;position:relative;z-index:1}.eyebrow{font-size:9px;letter-spacing:.22em;text-transform:uppercase;color:var(--rose-deep);font-weight:600}.hero h1{font:500 clamp(44px,5.4vw,77px)/1.04 var(--serif);letter-spacing:-.04em;margin:20px 0 18px;max-width:510px}.hero h1 em{color:var(--rose-deep);font-weight:500}.hero-copy p{font-size:13px;line-height:1.9;color:#716764;max-width:360px;margin:0 0 28px}.button{display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:15px 24px;font-size:10px;text-transform:uppercase;letter-spacing:.14em;transition:all .2s;cursor:pointer}.button-dark{background:var(--ink);color:white;border:1px solid var(--ink)}.button-dark:hover{background:var(--rose-deep);border-color:var(--rose-deep);transform:translateY(-2px)}.button-quiet{border:1px solid #b9aaa4;background:transparent;margin-left:8px}.button-quiet:hover{background:#fff}.hero-photo{min-height:530px;background-image:url('https://images.unsplash.com/photo-1488426862026-3ee34a7d66df?auto=format&fit=crop&w=1500&q=85');background-size:cover;background-position:center 39%;position:relative}.hero-photo:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(240,228,225,.22),transparent 35%)}.hero-note{position:absolute;right:25px;bottom:23px;color:white;font-size:9px;letter-spacing:.2em;text-transform:uppercase;text-shadow:0 1px 10px #333}.section{padding:88px 7%}.section-head{text-align:center;margin-bottom:38px}.section-head .eyebrow{color:var(--muted)}.section-head h2{font:500 clamp(32px,4vw,47px)/1.15 var(--serif);margin:12px 0 9px}.section-head p{font-size:12px;color:var(--muted);margin:0}.category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:17px;max-width:1220px;margin:auto}.category-card{position:relative;height:300px;overflow:hidden;background:#e9dfdb}.category-card img{width:100%;height:100%;object-fit:cover;transition:transform .65s}.category-card:hover img{transform:scale(1.045)}.category-card:after{content:'';position:absolute;inset:40% 0 0;background:linear-gradient(transparent,rgba(30,22,20,.54))}.category-label{position:absolute;z-index:1;bottom:21px;left:20px;color:#fff}.category-label small{font-size:9px;letter-spacing:.17em;text-transform:uppercase;display:block;margin-bottom:5px}.category-label strong{font:500 24px var(--serif)}.products-section{background:#fff}.product-grid{max-width:1220px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.product-card{min-width:0}.product-image{aspect-ratio: .84;background:#f1efed;position:relative;overflow:hidden}.product-image img{width:100%;height:100%;object-fit:cover;transition:transform .55s}.product-card:hover .product-image img{transform:scale(1.04)}.product-tag{position:absolute;top:13px;left:13px;background:#fff;padding:6px 8px;font-size:8px;letter-spacing:.13em;text-transform:uppercase}.wish{position:absolute;top:10px;right:11px;border:0;background:#ffffffd9;border-radius:50%;width:32px;height:32px;font-size:17px;cursor:pointer}.product-info{padding:14px 2px}.product-info small{color:var(--muted);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.product-info h3{font:500 17px var(--serif);margin:7px 0}.price{font-size:11px}.product-add{display:block;width:100%;border:1px solid var(--line);padding:11px;margin-top:12px;background:transparent;font-size:9px;letter-spacing:.13em;text-transform:uppercase;cursor:pointer;transition:all .2s}.product-add:hover{background:var(--ink);border-color:var(--ink);color:#fff}.collection{padding:0 7% 86px}.collection-panel{max-width:1220px;min-height:340px;margin:auto;display:grid;grid-template-columns:1.1fr .9fr;background:#efe4e0;overflow:hidden}.collection-image{background:url('https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=1200&q=85') center 37%/cover}.collection-copy{align-self:center;padding:50px 12%}.collection-copy h2{font:500 clamp(35px,4vw,52px)/1.12 var(--serif);margin:15px 0}.collection-copy p{font-size:12px;line-height:1.9;color:var(--muted);margin-bottom:24px}.footer{background:#211c1b;color:#f9f4f1;padding:52px 7% 24px}.footer-top{max-width:1220px;margin:auto;display:flex;justify-content:space-between;gap:30px;align-items:start}.footer-brand{font:500 25px var(--serif);letter-spacing:.12em}.footer p{font-size:11px;color:#c2b8b4;line-height:1.8;max-width:290px}.footer-links{display:flex;gap:25px;font-size:10px;color:#e4dcd8}.footer-bottom{border-top:1px solid #48403d;margin:36px auto 0;padding-top:18px;max-width:1220px;color:#a99f9b;font-size:9px;display:flex;justify-content:space-between;letter-spacing:.08em}.toast{position:fixed;z-index:5;bottom:24px;left:50%;transform:translate(-50%,20px);background:var(--ink);color:#fff;padding:13px 20px;font-size:12px;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}
        @media(max-width:800px){.header-main{height:68px;padding:0 5%;grid-template-columns:1fr auto 1fr}.menu-toggle{display:inline-flex;border:0;background:none;padding:8px;font-size:10px;letter-spacing:.12em}.brand{font-size:22px}.header-tools{gap:10px}.header-tools .icon-link span:not(.cart-count){display:none}.nav{display:none;height:auto;padding:12px 5% 20px;align-items:stretch;gap:0;flex-direction:column}.nav.open{display:flex}.nav a{padding:13px 2px;border-bottom:1px solid var(--line)}.hero{padding:0}.hero-panel{grid-template-columns:1fr;min-height:0}.hero-copy{padding:56px 8% 43px}.hero h1{font-size:clamp(43px,11vw,65px)}.hero-photo{min-height:340px;background-position:center 35%}.section{padding:64px 5%}.category-grid{grid-template-columns:repeat(2,1fr);gap:11px}.category-card{height:250px}.product-grid{grid-template-columns:repeat(2,1fr);gap:19px 12px}.collection{padding:0 5% 60px}.collection-panel{grid-template-columns:1fr}.collection-image{min-height:290px}.collection-copy{padding:36px 8% 44px}.footer{padding:42px 6% 22px}.footer-top{flex-direction:column}.footer-links{flex-wrap:wrap;gap:18px}.footer-bottom{gap:12px;flex-wrap:wrap}}
        @media(max-width:390px){.header-tools{gap:3px}.hero-copy .button{padding:13px 15px}.button-quiet{margin:8px 0 0}.category-card{height:210px}.category-label{left:13px;bottom:15px}.category-label strong{font-size:21px}}
    </style>
</head>
<body>
    <div class="announcement">Une touche de beauté en plus <span>— livraison offerte dès 500 MAD</span></div>
    <header class="site-header">
        <div class="header-main">
            <button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav">☰ &nbsp; MENU</button>
            <a class="brand" href="#accueil" aria-label="Éclora Beauty, accueil">ÉCLORA<span>.</span></a>
            <div class="header-tools">
                <button class="icon-link" type="button" aria-label="Rechercher" onclick="document.getElementById('best-sellers').scrollIntoView({behavior:'smooth'})"><svg viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 4.5 4.5"/></svg><span>Recherche</span></button>
                <button class="icon-link" type="button" aria-label="Favoris" onclick="showToast('Vos favoris vous attendent bientôt.')"><svg viewBox="0 0 24 24"><path d="M20.5 8.8c0 5.2-8.5 10-8.5 10s-8.5-4.8-8.5-10A4.3 4.3 0 0 1 12 6.4a4.3 4.3 0 0 1 8.5 2.4Z"/></svg></button>
                <button class="icon-link" type="button" aria-label="Panier"><svg viewBox="0 0 24 24"><path d="M5 8h14l1 12H4L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg><span class="cart-count" id="cart-count">0</span></button>
            </div>
        </div>
        <nav class="nav" id="main-nav" aria-label="Navigation principale"><a href="#accueil">Accueil</a><a href="#categories">Maquillage</a><a href="#best-sellers">Nouveautés</a><a href="#collection">Notre univers</a><a href="#contact">Contact</a></nav>
    </header>
    <main>
        <section class="hero" id="accueil" aria-label="Nouvelle collection">
            <div class="hero-panel">
                <div class="hero-copy"><span class="eyebrow">La nouvelle collection · 2026</span><h1>Votre beauté,<br><em>en toute lumière.</em></h1><p>Des essentiels choisis avec soin pour révéler votre éclat, chaque jour et à votre façon.</p><a class="button button-dark" href="#best-sellers">Découvrir la collection <span aria-hidden="true">→</span></a><a class="button button-quiet" href="#categories">Nos essentiels</a></div>
                <div class="hero-photo" role="img" aria-label="Portrait beauté lumineux dans des tons doux"><span class="hero-note">L’éclat au naturel</span></div>
            </div>
        </section>
        <section class="section" id="categories"><div class="section-head"><span class="eyebrow">Trouvez votre rituel</span><h2>La beauté, selon vous</h2><p>Quelques essentiels pour accompagner chaque moment.</p></div>
            <div class="category-grid">
                <a class="category-card" href="#best-sellers"><img loading="lazy" src="https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80" alt="Maquillage dans des tons chauds"><span class="category-label"><small>Le teint parfait</small><strong>Visage</strong></span></a>
                <a class="category-card" href="#best-sellers"><img loading="lazy" src="https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80" alt="Produits de beauté et maquillage"><span class="category-label"><small>Un regard qui révèle</small><strong>Yeux</strong></span></a>
                <a class="category-card" href="#best-sellers"><img loading="lazy" src="https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80" alt="Rouge à lèvres rose"><span class="category-label"><small>La nuance juste</small><strong>Lèvres</strong></span></a>
                <a class="category-card" href="#best-sellers"><img loading="lazy" src="https://images.unsplash.com/photo-1608248543803-ba4f8c70ae0b?auto=format&fit=crop&w=800&q=80" alt="Soin de beauté présenté avec élégance"><span class="category-label"><small>Le temps de prendre soin</small><strong>Soins</strong></span></a>
            </div>
        </section>
        <section class="section products-section" id="best-sellers"><div class="section-head"><span class="eyebrow">Vos coups de cœur</span><h2>Les essentiels Éclora</h2><p>Des textures sensorielles et des teintes faciles à aimer.</p></div>
            <div class="product-grid">
                <article class="product-card"><div class="product-image"><img loading="lazy" src="https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=800&q=80" alt="Palette de maquillage aux tons naturels"><span class="product-tag">Best-seller</span><button class="wish" type="button" aria-label="Ajouter la palette aux favoris" onclick="this.classList.toggle('active'); this.textContent=this.classList.contains('active')?'♥':'♡'">♡</button></div><div class="product-info"><small>Le regard</small><h3>Palette Nude Lumière</h3><span class="price">189 MAD</span><button class="product-add" type="button" onclick="addToCart('Palette Nude Lumière')">Ajouter au panier</button></div></article>
                <article class="product-card"><div class="product-image"><img loading="lazy" src="https://images.unsplash.com/photo-1586495777744-4413f21062fa?auto=format&fit=crop&w=800&q=80" alt="Rouge à lèvres dans une nuance rosée"><span class="product-tag">Nouveau</span><button class="wish" type="button" aria-label="Ajouter le rouge à lèvres aux favoris" onclick="this.classList.toggle('active'); this.textContent=this.classList.contains('active')?'♥':'♡'">♡</button></div><div class="product-info"><small>Les lèvres</small><h3>Rouge Satin Rosé</h3><span class="price">129 MAD</span><button class="product-add" type="button" onclick="addToCart('Rouge Satin Rosé')">Ajouter au panier</button></div></article>
                <article class="product-card"><div class="product-image"><img loading="lazy" src="https://images.unsplash.com/photo-1608248543803-ba4f8c70ae0b?auto=format&fit=crop&w=800&q=80" alt="Soin visage délicat"><span class="product-tag">Rituel douceur</span><button class="wish" type="button" aria-label="Ajouter le soin aux favoris" onclick="this.classList.toggle('active'); this.textContent=this.classList.contains('active')?'♥':'♡'">♡</button></div><div class="product-info"><small>Le soin</small><h3>Crème Voile de Rosée</h3><span class="price">219 MAD</span><button class="product-add" type="button" onclick="addToCart('Crème Voile de Rosée')">Ajouter au panier</button></div></article>
                <article class="product-card"><div class="product-image"><img loading="lazy" src="https://images.unsplash.com/photo-1523293182086-7651a899d37f?auto=format&fit=crop&w=800&q=80" alt="Flacon parfum posé sur une surface lumineuse"><span class="product-tag">Édition Éclora</span><button class="wish" type="button" aria-label="Ajouter le parfum aux favoris" onclick="this.classList.toggle('active'); this.textContent=this.classList.contains('active')?'♥':'♡'">♡</button></div><div class="product-info"><small>Le parfum</small><h3>Eau de Parfum Rosée</h3><span class="price">299 MAD</span><button class="product-add" type="button" onclick="addToCart('Eau de Parfum Rosée')">Ajouter au panier</button></div></article>
            </div>
        </section>
        <section class="collection" id="collection"><div class="collection-panel"><div class="collection-image" role="img" aria-label="Portrait éditorial de beauté naturelle"></div><div class="collection-copy"><span class="eyebrow">Notre philosophie</span><h2>La beauté vous ressemble.</h2><p>Nous croyons aux gestes simples, aux nuances qui vous font du bien et aux instants que l’on s’accorde. Bienvenue dans l’univers Éclora.</p><a class="button button-dark" href="#contact">En savoir plus <span aria-hidden="true">→</span></a></div></div></section>
    </main>
    <footer class="footer" id="contact"><div class="footer-top"><div><div class="footer-brand">ÉCLORA BEAUTY</div><p>Une beauté douce, lumineuse et libre. Des essentiels sélectionnés avec amour au Maroc.</p></div><div class="footer-links"><a href="#categories">Maquillage</a><a href="#best-sellers">Nos produits</a><a href="https://instagram.com" target="_blank" rel="noreferrer">Instagram</a><a href="mailto:bonjour@eclora.ma">Nous écrire</a></div></div><div class="footer-bottom"><span>© 2026 Éclora Beauty · Maroc</span><span>Livraison offerte dès 500 MAD</span></div></footer>
    <div class="toast" id="toast" role="status" aria-live="polite"></div>
    <script>
        const navToggle=document.querySelector('.menu-toggle');const mainNav=document.getElementById('main-nav');navToggle.addEventListener('click',()=>{const isOpen=mainNav.classList.toggle('open');navToggle.setAttribute('aria-expanded',String(isOpen));});mainNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{mainNav.classList.remove('open');navToggle.setAttribute('aria-expanded','false');}));let cartCount=0;function addToCart(name){cartCount+=1;document.getElementById('cart-count').textContent=String(cartCount);showToast(name+' ajouté à votre panier.')}let toastTimer;function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
    </script>
</body>
</html>
